create temp table cmp_actual (k text primary key, v jsonb);
insert into cmp_actual
select 'fn:' || p.proname || '(' || pg_catalog.pg_get_function_identity_arguments(p.oid) || ')', pg_catalog.jsonb_build_object(
    'identity_args', pg_catalog.pg_get_function_identity_arguments(p.oid), 'args', pg_catalog.pg_get_function_arguments(p.oid),
    'result', pg_catalog.pg_get_function_result(p.oid), 'kind', p.prokind, 'volatility', p.provolatile, 'strict', p.proisstrict,
    'security_definer', p.prosecdef, 'parallel', p.proparallel, 'leakproof', p.proleakproof, 'config', p.proconfig,
    'owner', pg_catalog.pg_get_userbyid(p.proowner), 'acl', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('grantor', pg_catalog.pg_get_userbyid(x.grantor),
      'grantee', case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, 'privilege', x.privilege_type, 'grantable', x.is_grantable)
      order by case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, x.privilege_type, pg_catalog.pg_get_userbyid(x.grantor))
     from pg_catalog.aclexplode(coalesce(p.proacl, pg_catalog.acldefault('f', p.proowner))) x),
    'def_md5', pg_catalog.md5(pg_catalog.pg_get_functiondef(p.oid)))
from pg_catalog.pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('zell_valid_benefits', 'zell_save_shipping', 'zell_save_identity', 'zell_reorder_products', 'zell_reorder_product_images', 'zell_set_primary_product_image');
insert into cmp_actual
select 'fn_count:' || n, pg_catalog.to_jsonb((select pg_catalog.count(*) from pg_catalog.pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname = n))
from pg_catalog.unnest(array['zell_valid_benefits', 'zell_save_shipping', 'zell_save_identity', 'zell_reorder_products', 'zell_reorder_product_images', 'zell_set_primary_product_image']) n;
insert into cmp_actual select 'admin_users:columns', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('num', a.attnum, 'name', a.attname,
    'type', pg_catalog.format_type(a.atttypid, a.atttypmod), 'not_null', a.attnotnull, 'default', pg_catalog.pg_get_expr(d.adbin, d.adrelid),
    'identity', a.attidentity, 'generated', a.attgenerated, 'column_acl', a.attacl) order by a.attnum)
  from pg_catalog.pg_attribute a left join pg_catalog.pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
  where a.attrelid = pg_catalog.to_regclass('public.admin_users') and a.attnum > 0 and not a.attisdropped);
insert into cmp_actual select 'admin_users:constraints', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', c.conname, 'type', c.contype,
    'def', pg_catalog.pg_get_constraintdef(c.oid)) order by c.conname) from pg_catalog.pg_constraint c where c.conrelid = pg_catalog.to_regclass('public.admin_users'));
insert into cmp_actual select 'admin_users:indexes', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', ic.relname, 'def', pg_catalog.pg_get_indexdef(x.indexrelid)) order by ic.relname)
  from pg_catalog.pg_index x join pg_catalog.pg_class ic on ic.oid = x.indexrelid where x.indrelid = pg_catalog.to_regclass('public.admin_users'));
insert into cmp_actual select 'admin_users:table', (select pg_catalog.jsonb_build_object('owner', pg_catalog.pg_get_userbyid(c.relowner), 'rls', c.relrowsecurity,
    'force_rls', c.relforcerowsecurity, 'acl', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('grantor', pg_catalog.pg_get_userbyid(x.grantor),
      'grantee', case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, 'privilege', x.privilege_type, 'grantable', x.is_grantable)
      order by case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, x.privilege_type)
     from pg_catalog.aclexplode(coalesce(c.relacl, pg_catalog.acldefault('r', c.relowner))) x)) from pg_catalog.pg_class c where c.oid = pg_catalog.to_regclass('public.admin_users'));
insert into cmp_actual select 'admin_users:triggers', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', t.tgname, 'enabled', t.tgenabled,
    'def', pg_catalog.pg_get_triggerdef(t.oid)) order by t.tgname) from pg_catalog.pg_trigger t where t.tgrelid = pg_catalog.to_regclass('public.admin_users') and not t.tgisinternal);
insert into cmp_actual select 'admin_users:policies', pg_catalog.to_jsonb((select pg_catalog.count(*) from pg_catalog.pg_policy p where p.polrelid = pg_catalog.to_regclass('public.admin_users')));
insert into cmp_actual
select 'col:' || t.tbl || '.' || t.col, pg_catalog.jsonb_build_object('num', a.attnum,
    'position', (select pg_catalog.count(*) from pg_catalog.pg_attribute b where b.attrelid = a.attrelid and b.attnum > 0 and not b.attisdropped and b.attnum <= a.attnum),
    'type', pg_catalog.format_type(a.atttypid, a.atttypmod), 'typmod', a.atttypmod, 'not_null', a.attnotnull, 'default', pg_catalog.pg_get_expr(d.adbin, d.adrelid),
    'identity', a.attidentity, 'generated', a.attgenerated,
    'collation', case when a.attcollation <> 0 and a.attcollation <> ty.typcollation then (select co.collname from pg_catalog.pg_collation co where co.oid = a.attcollation) end,
    'column_acl', a.attacl, 'comment', pg_catalog.col_description(a.attrelid, a.attnum))
from (values ('product_images', 'fit'), ('products', 'after_image'), ('products', 'before_image'), ('products', 'benefits'), ('products', 'brand'), ('products', 'images'), ('products', 'short_benefit')) t(tbl, col)
join pg_catalog.pg_attribute a on a.attrelid = pg_catalog.to_regclass('public.' || t.tbl) and a.attname = t.col and a.attnum > 0 and not a.attisdropped
join pg_catalog.pg_type ty on ty.oid = a.atttypid
left join pg_catalog.pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum;
insert into cmp_actual select 'cols:constraints', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('table', c.conrelid::regclass::text, 'name', c.conname,
    'type', c.contype, 'def', pg_catalog.pg_get_constraintdef(c.oid),
    'columns', (select pg_catalog.jsonb_agg(a.attname order by a.attnum) from pg_catalog.pg_attribute a where a.attrelid = c.conrelid and a.attnum = any (c.conkey)),
    'validated', c.convalidated) order by c.conrelid::regclass::text, c.conname)
  from pg_catalog.pg_constraint c
  where exists (select 1 from (values ('product_images', 'fit'), ('products', 'after_image'), ('products', 'before_image'), ('products', 'benefits'), ('products', 'brand'), ('products', 'images'), ('products', 'short_benefit')) t(tbl, col) join pg_catalog.pg_attribute a on a.attrelid = pg_catalog.to_regclass('public.' || t.tbl) and a.attname = t.col
                where a.attrelid = c.conrelid and a.attnum = any (c.conkey)));
insert into cmp_actual select 'cols:indexes', pg_catalog.to_jsonb((select pg_catalog.count(distinct x.indexrelid) from pg_catalog.pg_index x
  join (values ('product_images', 'fit'), ('products', 'after_image'), ('products', 'before_image'), ('products', 'benefits'), ('products', 'brand'), ('products', 'images'), ('products', 'short_benefit')) t(tbl, col) on x.indrelid = pg_catalog.to_regclass('public.' || t.tbl)
  join pg_catalog.pg_attribute a on a.attrelid = x.indrelid and a.attname = t.col
  where a.attnum = any (x.indkey::int2[]) or exists (select 1 from pg_catalog.pg_depend dp where dp.classid = 'pg_catalog.pg_class'::regclass
    and dp.objid = x.indexrelid and dp.refobjid = x.indrelid and dp.refobjsubid = a.attnum)));
insert into cmp_actual
select 'order:' || t.tbl, pg_catalog.to_jsonb((select pg_catalog.string_agg(a.attnum || ':' || a.attname, ',' order by a.attnum)
  from pg_catalog.pg_attribute a where a.attrelid = pg_catalog.to_regclass('public.' || t.tbl) and a.attnum > 0 and not a.attisdropped))
from (values ('products'), ('product_images')) t(tbl);
insert into cmp_actual
select 'otbl:' || t.tbl, (select pg_catalog.jsonb_build_object('owner', pg_catalog.pg_get_userbyid(c.relowner), 'rls', c.relrowsecurity, 'force_rls', c.relforcerowsecurity,
    'acl', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('grantor', pg_catalog.pg_get_userbyid(x.grantor),
      'grantee', case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, 'privilege', x.privilege_type, 'grantable', x.is_grantable)
      order by case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, x.privilege_type)
     from pg_catalog.aclexplode(coalesce(c.relacl, pg_catalog.acldefault('r', c.relowner))) x),
    'live_columns', (select pg_catalog.count(*) from pg_catalog.pg_attribute a where a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped))
  from pg_catalog.pg_class c where c.oid = pg_catalog.to_regclass('public.' || t.tbl))
from (values ('orders'), ('order_items')) t(tbl);
insert into cmp_actual
select 'ocols:' || t.tbl, coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'position', (select pg_catalog.count(*) from pg_catalog.pg_attribute b where b.attrelid = a.attrelid and b.attnum > 0 and not b.attisdropped and b.attnum <= a.attnum),
    'column', a.attname, 'type', pg_catalog.format_type(a.atttypid, a.atttypmod), 'typmod', a.atttypmod, 'not_null', a.attnotnull,
    'default', pg_catalog.pg_get_expr(d.adbin, d.adrelid), 'identity', a.attidentity, 'generated', a.attgenerated,
    'collation', case when a.attcollation <> 0 and a.attcollation <> ty.typcollation then (select co.collname from pg_catalog.pg_collation co where co.oid = a.attcollation) end,
    'column_acl', (select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('grantor', pg_catalog.pg_get_userbyid(x.grantor),
        'grantee', case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, 'privilege', x.privilege_type, 'grantable', x.is_grantable)
      order by case when x.grantee = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(x.grantee) end, x.privilege_type) from pg_catalog.aclexplode(a.attacl) x),
    'comment', pg_catalog.col_description(a.attrelid, a.attnum)) order by a.attnum)
  from pg_catalog.pg_attribute a join pg_catalog.pg_type ty on ty.oid = a.atttypid
  left join pg_catalog.pg_attrdef d on d.adrelid = a.attrelid and d.adnum = a.attnum
  where a.attrelid = pg_catalog.to_regclass('public.' || t.tbl) and a.attnum > 0 and not a.attisdropped), '[]'::jsonb)
from (values ('orders'), ('order_items')) t(tbl);
insert into cmp_actual
select 'ocons:' || t.tbl, coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', c.conname, 'type', c.contype, 'def', pg_catalog.pg_get_constraintdef(c.oid),
    'columns', (select pg_catalog.jsonb_agg(a.attname order by a.attnum) from pg_catalog.pg_attribute a where a.attrelid = c.conrelid and a.attnum = any (c.conkey)),
    'ref_table', case when c.confrelid <> 0 then c.confrelid::regclass::text end, 'validated', c.convalidated, 'deferrable', c.condeferrable,
    'deferred', c.condeferred, 'no_inherit', c.connoinherit) order by c.conname)
  from pg_catalog.pg_constraint c where c.conrelid = pg_catalog.to_regclass('public.' || t.tbl)), '[]'::jsonb)
from (values ('orders'), ('order_items')) t(tbl);
insert into cmp_actual
select 'oidx:' || t.tbl, coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', ic.relname, 'def', pg_catalog.pg_get_indexdef(x.indexrelid),
    'unique', x.indisunique, 'primary', x.indisprimary, 'valid', x.indisvalid,
    'constraint', (select co.conname from pg_catalog.pg_constraint co where co.conindid = x.indexrelid and co.conrelid = x.indrelid order by co.conname limit 1))
    order by ic.relname)
  from pg_catalog.pg_index x join pg_catalog.pg_class ic on ic.oid = x.indexrelid where x.indrelid = pg_catalog.to_regclass('public.' || t.tbl)), '[]'::jsonb)
from (values ('orders'), ('order_items')) t(tbl);
insert into cmp_actual
select 'otrg:' || t.tbl, coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', g.tgname, 'enabled', g.tgenabled, 'def', pg_catalog.pg_get_triggerdef(g.oid)) order by g.tgname)
  from pg_catalog.pg_trigger g where g.tgrelid = pg_catalog.to_regclass('public.' || t.tbl) and not g.tgisinternal), '[]'::jsonb)
from (values ('orders'), ('order_items')) t(tbl);
insert into cmp_actual
select 'opol:' || t.tbl, coalesce((select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object('name', p.polname, 'cmd', p.polcmd, 'permissive', p.polpermissive,
    'roles', (select pg_catalog.jsonb_agg(case when r = 0 then 'PUBLIC' else pg_catalog.pg_get_userbyid(r) end order by 1) from pg_catalog.unnest(p.polroles) r),
    'qual', pg_catalog.pg_get_expr(p.polqual, p.polrelid), 'with_check', pg_catalog.pg_get_expr(p.polwithcheck, p.polrelid)) order by p.polname)
  from pg_catalog.pg_policy p where p.polrelid = pg_catalog.to_regclass('public.' || t.tbl)), '[]'::jsonb)
from (values ('orders'), ('order_items')) t(tbl);

select case when a.v = e.v then 'CMP PASS ' || e.k
            else 'CMP FAIL ' || e.k || ' :: expected=' || pg_catalog.left(e.v::text, 600) || ' actual=' || coalesce(pg_catalog.left(a.v::text, 600), '(missing)') end
from cmp_expected e left join cmp_actual a using (k) order by e.k;
select 'CMP EXPECTED ' || pg_catalog.count(*) from cmp_expected;
select 'CMP FAIL unexpected ' || a.k from cmp_actual a where not exists (select 1 from cmp_expected e where e.k = a.k);
-- element-level detail for array values that differ (what Production has that the build lacks, and the reverse)
select 'CMP DIFF ' || e.k || ' only_in_production=' || x::text
from cmp_expected e join cmp_actual a using (k), pg_catalog.jsonb_array_elements(e.v) x
where a.v is distinct from e.v and pg_catalog.jsonb_typeof(e.v) = 'array' and pg_catalog.jsonb_typeof(a.v) = 'array' and not (a.v @> pg_catalog.jsonb_build_array(x));
select 'CMP DIFF ' || a.k || ' only_in_build=' || y::text
from cmp_expected e join cmp_actual a using (k), pg_catalog.jsonb_array_elements(a.v) y
where a.v is distinct from e.v and pg_catalog.jsonb_typeof(e.v) = 'array' and pg_catalog.jsonb_typeof(a.v) = 'array' and not (e.v @> pg_catalog.jsonb_build_array(y));
do $d$ begin
  if exists (select 1 from cmp_expected e left join cmp_actual a using (k) where a.v is distinct from e.v)
     or exists (select 1 from cmp_actual a where not exists (select 1 from cmp_expected e where e.k = a.k)) then
    raise exception 'ZELL_BASELINE_COMPARE_FAILED';
  end if;
end $d$;
